func (this *Coinbase) ParseConversion(conversion any, optionalArgs ...any) Conversion {
	var fromCurrency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = fromCurrency
	var toCurrency map[string]any = GetArgMap(optionalArgs, 1, nil)
	_ = toCurrency
	var fromCoin *string = this.SafeString(conversion, "source_currency")
	var fromCode *string = this.SafeCurrencyCode(fromCoin, fromCurrency)
	var to *string = this.SafeString(conversion, "target_currency")
	var toCode *string = this.SafeCurrencyCode(to, toCurrency)
	var fromAmountStructure map[string]any = SafeMapTyped(conversion, "user_entered_amount")
	var feeStructure map[string]any = SafeMapTyped(conversion, "total_fee")
	var feeAmountStructure map[string]any = SafeMapTyped(feeStructure, "amount")
	return ConversionFromMap(map[string]any{
		"info":         conversion,
		"timestamp":    nil,
		"datetime":     nil,
		"id":           this.SafeString(conversion, "id"),
		"fromCurrency": fromCode,
		"fromAmount":   this.SafeNumber(fromAmountStructure, "value"),
		"toCurrency":   toCode,
		"toAmount":     nil,
		"price":        nil,
		"fee":          this.SafeNumber(feeAmountStructure, "value"),
	})
}

/**
 * @method
 * @name coinbase#transfer
 * @description transfer currency internally between portfolios of the same account
 * @see https://docs.cdp.coinbase.com/api-reference/advanced-trade-api/rest-api/portfolios/move-portfolios-funds
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount the portfolio uuid to transfer funds from
 * @param {string} toAccount the portfolio uuid to transfer funds to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Coinbase) TransferAsync(code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) <-chan AsyncResult[TransferEntry] {
	ch := make(chan AsyncResult[TransferEntry], 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Coinbase) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"funds": map[string]any{
			"value":    this.CurrencyToPrecision(code, amount),
			"currency": currency["id"],
		},
		"source_portfolio_uuid": fromAccount,
		"target_portfolio_uuid": toAccount,
	}

	r1 := <-this.V3PrivatePostBrokeragePortfoliosMoveFunds(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "source_portfolio_uuid": "8bfc20d7-f7c6-4422-bf07-8243ca4169fe",
	//         "target_portfolio_uuid": "8bfc20d7-f7c6-4422-bf07-8243ca4169fe"
	//     }
	//
	var transfer map[string]any = TransferEntryToMap(this.ParseTransfer(response, currency))
	transfer["amount"] = amount
	transfer["status"] = "ok"

	ch <- AsyncResult[TransferEntry]{Value: TransferEntryFromMap(transfer)}
	return nil
}
func (this *Coinbase) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	//     {
	//         "source_portfolio_uuid": "8bfc20d7-f7c6-4422-bf07-8243ca4169fe",
	//         "target_portfolio_uuid": "8bfc20d7-f7c6-4422-bf07-8243ca4169fe"
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyCode *string = this.SafeCurrencyCode(nil, currency)
	return TransferEntryFromMap(map[string]any{
		"info":        transfer,
		"id":          nil,
		"timestamp":   nil,
		"datetime":    nil,
		"currency":    currencyCode,
		"amount":      nil,
		"fromAccount": this.SafeString(transfer, "source_portfolio_uuid"),
		"toAccount":   this.SafeString(transfer, "target_portfolio_uuid"),
		"status":      nil,
	})
}

