func (this *Coinbase) FetchPortfolioDetailsAsync(portfolioUuid any, optionalArgs ...any) <-chan AsyncResult[[]map[string]any] {
	ch := make(chan AsyncResult[[]map[string]any], 1)
	go this.fetchPortfolioDetailsBody(ch, portfolioUuid, optionalArgs...)
	return ch
}
func (this *Coinbase) fetchPortfolioDetailsBody(ch chan AsyncResult[[]map[string]any], portfolioUuid any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = map[string]any{
		"portfolio_uuid": portfolioUuid,
	}

	r1 := <-this.V3PrivateGetBrokeragePortfoliosPortfolioUuid(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var result []any = this.ParsePortfolioDetails(response)

	ch <- AsyncResult[[]map[string]any]{Value: MapSliceFromList(result)}
	return nil
}
func (this *Coinbase) ParsePortfolioDetails(portfolioData any) []any {
	var breakdown map[string]any = SafeMapTyped(portfolioData, "breakdown")
	var portfolioInfo map[string]any = SafeMapTyped(breakdown, "portfolio")
	var portfolioName *string = this.SafeString(portfolioInfo, "name", "Unknown")
	var portfolioUuid *string = this.SafeString(portfolioInfo, "uuid", "")
	var spotPositions []any = SafeListTyped(breakdown, "spot_positions")
	var parsedPositions []any = []any{}
	for i := 0; i < len(spotPositions); i++ {
		var position map[string]any = MapTyped(spotPositions[i])
		var currencyCode *string = this.SafeString(position, "asset", "Unknown")
		var availableBalanceStr *string = this.SafeString(position, "available_to_trade_fiat", "0")
		var availableBalance *float64 = this.ParseNumber(availableBalanceStr)
		var totalBalanceFiatStr *string = this.SafeString(position, "total_balance_fiat", "0")
		var totalBalanceFiat *float64 = this.ParseNumber(totalBalanceFiatStr)
		var holdAmount any = 0
		if (totalBalanceFiat != nil) && (availableBalance != nil) && (*totalBalanceFiat > *availableBalance) {
			holdAmount = (*totalBalanceFiat - *availableBalance)
		}
		var costBasisDict map[string]any = SafeMapTyped(position, "cost_basis")
		var costBasisStr *string = this.SafeString(costBasisDict, "value", "0")
		var averageEntryPriceDict map[string]any = SafeMapTyped(position, "average_entry_price")
		var averageEntryPriceStr *string = this.SafeString(averageEntryPriceDict, "value", "0")
		var positionData map[string]any = map[string]any{
			"currency":                     currencyCode,
			"available_balance":            availableBalance,
			"hold_amount":                  holdAmount,
			"wallet_name":                  portfolioName,
			"account_id":                   portfolioUuid,
			"account_uuid":                 this.SafeString(position, "account_uuid", ""),
			"total_balance_fiat":           totalBalanceFiat,
			"total_balance_crypto":         this.ParseNumber(this.SafeString(position, "total_balance_crypto", "0")),
			"available_to_trade_fiat":      this.ParseNumber(this.SafeString(position, "available_to_trade_fiat", "0")),
			"available_to_trade_crypto":    this.ParseNumber(this.SafeString(position, "available_to_trade_crypto", "0")),
			"available_to_transfer_fiat":   this.ParseNumber(this.SafeString(position, "available_to_transfer_fiat", "0")),
			"available_to_transfer_crypto": this.ParseNumber(this.SafeString(position, "available_to_trade_crypto", "0")),
			"allocation":                   this.ParseNumber(this.SafeString(position, "allocation", "0")),
			"cost_basis":                   this.ParseNumber(costBasisStr),
			"cost_basis_currency":          this.SafeString(costBasisDict, "currency", "USD"),
			"is_cash":                      this.SafeBool(position, "is_cash", false),
			"average_entry_price":          this.ParseNumber(averageEntryPriceStr),
			"average_entry_price_currency": this.SafeString(averageEntryPriceDict, "currency", "USD"),
			"asset_uuid":                   this.SafeString(position, "asset_uuid", ""),
			"unrealized_pnl":               this.ParseNumber(this.SafeString(position, "unrealized_pnl", "0")),
			"asset_color":                  this.SafeString(position, "asset_color", ""),
			"account_type":                 this.SafeString(position, "account_type", ""),
		}
		parsedPositions = append(parsedPositions, positionData)
	}
	return parsedPositions
}

/**
 * @method
 * @name coinbase#isEddsaApiKey
 * @ignore
 * @description checks whether the secret is a v2 (Ed25519) CDP api key secret
 * @returns {boolean} true if the secret is an Ed25519 key
 */
func (this *Coinbase) IsEddsaApiKey() bool {
	// using the size might be fragile, so we add an option to force v2 cloud api key if needed
	return (GetLength(this.Secret) == 88) || (*this.SafeBool(this.Options, "v2CloudAPiKey", false)) || strings.HasSuffix(this.Secret, "=")
}
func (this *Coinbase) CreateAuthToken(seconds any, url string, optionalArgs ...any) string {
	// v1 https://docs.cdp.coinbase.com/api-reference/authentication#php-2
	// v2  https://docs.cdp.coinbase.com/api-reference/v2/authentication
	var method *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = method
	var useEddsa bool = GetArgBool(optionalArgs, 1, false)
	_ = useEddsa
	var uri any = nil
	if url != "" {
		uri = Add(Add(method, " "), strings.Replace(url, "https://", "", 1))
		var quesPos int = GetIndexOf(uri, "?")
		// Due to we use mb_strpos, quesPos could be false in php. In that case, the quesPos >= 0 is true
		// Also it's not possible that the question mark is first character, only check > 0 here.
		if quesPos > 0 {
			uri = Slice(uri, 0, quesPos)
		}
	}
	// eddsa {"sub":"d2efa49a-369c-43d7-a60e-ae26e28853c2","iss":"cdp","aud":["cdp_service"],"uris":["GET api.coinbase.com/api/v3/brokerage/transaction_summary"]}
	var nonce string = this.RandomBytes(16)
	var aud string = "retail_rest_api_proxy"
	if useEddsa == true {
		aud = "cdp_service"
	}
	var iss string = "coinbase-cloud"
	if useEddsa == true {
		iss = "cdp"
	}
	var request map[string]any = map[string]any{
		"aud": []any{aud},
		"iss": iss,
		"nbf": seconds,
		"exp": Add(seconds, 120),
		"sub": this.ApiKey,
		"iat": seconds,
	}
	if uri != nil {
		if !(useEddsa == true) {
			request["uri"] = uri
		} else {
			request["uris"] = []any{uri}
		}
	}
	if useEddsa == true {
		var byteArray []byte = this.Base64ToBinary(this.Secret)
		var seed []any = this.ArraySlice(byteArray, 0, 32)
		return Jwt(request, seed, sha256, false, map[string]any{
			"kid":   this.ApiKey,
			"nonce": nonce,
			"alg":   "EdDSA",
		})
	} else {
		// ecdsa with p256
		return Jwt(request, this.Encode(this.Secret), sha256, false, map[string]any{
			"kid":   this.ApiKey,
			"nonce": nonce,
			"alg":   "ES256",
		})
	}
}
func (this *Coinbase) Nonce() int64 {
	var timeDifference *int64 = this.SafeInteger(this.Options, "timeDifference")
	if timeDifference == nil {
		panic(ExchangeError(this.Id + " nonce() requires a numeric options[\"timeDifference\"]"))
	}
	return this.Milliseconds() - *timeDifference
}
func (this *Coinbase) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var requestBody *string = nil
	var requestHeaders any = nil
	var version string = api[0]
	var signed bool = (api[1] == "private")
	var isV3 bool = (version == "v3")
	var pathPart string = "v2"
	if isV3 {
		pathPart = "api/v3"
	}
	var fullPath string = "/" + pathPart + "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	var savedPath string = fullPath
	queryMap, _ := query.(map[string]any)
	var queryLength int = len(queryMap)
	if method == "GET" {
		if queryLength > 0 {
			fullPath += "?" + this.UrlencodeWithArrayRepeat(query)
		}
	}
	var apiUrl *string = this.SafeString(this.Urls["api"], "rest")
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + fullPath
	if signed {
		var authorization *string = this.SafeString(this.Headers, "Authorization")
		var authorizationString any = nil
		if authorization != nil {
			authorizationString = authorization
		} else if (this.Token != "") && !this.CheckRequiredCredentials(false) {
			authorizationString = Add("Bearer ", this.Token)
		} else {
			this.CheckRequiredCredentials()
			var seconds int64 = this.Seconds()
			var payload string = ""
			if method != "GET" {
				if queryLength > 0 {
					payload = this.Json(query)
					requestBody = SafeStringPtr(payload)
				}
			} else {
				if !isV3 {
					if queryLength > 0 {
						payload = "?" + this.Urlencode(query)
					}
				}
			}
			// v3: 'GET' doesn't need payload in the signature. inside url is enough
			// https://docs.cdp.coinbase.com/coinbase-app/authentication-authorization/api-key-authentication
			// v2: 'GET' require payload in the signature
			// https://docs.cdp.coinbase.com/coinbase-app/authentication-authorization/api-key-authentication
			var isCloudAPiKey bool = (strings.Index(this.ApiKey, "organizations/") >= 0) || (strings.HasPrefix(this.Secret, "-----BEGIN"))
			var isV2CloudAPiKey bool = this.IsEddsaApiKey()
			if isCloudAPiKey || isV2CloudAPiKey {
				if isCloudAPiKey && strings.HasPrefix(this.ApiKey, "-----BEGIN") {
					panic(ArgumentsRequired(this.Id + " apiKey should contain the name (eg: organizations/3b910e93....) and not the public key"))
				}
				// // it may not work for v2
				// let uri = method + ' ' + url.replace ('https://', '');
				// const quesPos = uri.indexOf ('?');
				// // Due to we use mb_strpos, quesPos could be false in php. In that case, the quesPos >= 0 is true
				// // Also it's not possible that the question mark is first character, only check > 0 here.
				// if (quesPos > 0) {
				//     uri = uri.slice (0, quesPos);
				// }
				// const nonce = this.randomBytes (16);
				// const request: Dict = {
				//     'aud': [ 'retail_rest_api_proxy' ],
				//     'iss': 'coinbase-cloud',
				//     'nbf': seconds,
				//     'exp': seconds + 120,
				//     'sub': this.apiKey,
				//     'uri': uri,
				//     'iat': seconds,
				// };
				var token string = this.CreateAuthToken(seconds, url, method, isV2CloudAPiKey)
				// const token = jwt (request, this.encode (this.secret), sha256, false, { 'kid': this.apiKey, 'nonce': nonce, 'alg': 'ES256' });
				authorizationString = "Bearer " + token
			} else {
				var nonce int64 = this.ParseToInt(this.Nonce())
				var timestamp int64 = this.ParseToInt(float64(nonce) / 1000)
				var timestampString string = strconv.FormatInt(timestamp, 10)
				var auth string = timestampString + method + savedPath + payload
				var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256)
				requestHeaders = map[string]any{
					"CB-ACCESS-KEY":       this.ApiKey,
					"CB-ACCESS-SIGN":      signature,
					"CB-ACCESS-TIMESTAMP": timestampString,
					"Content-Type":        "application/json",
				}
			}
		}
		if !IsEqual(authorizationString, nil) {
			requestHeaders = map[string]any{
				"Authorization": authorizationString,
				"Content-Type":  "application/json",
			}
			if method != "GET" {
				if queryLength > 0 {
					jsonText := this.Json(query)
					requestBody = &jsonText
				}
			}
		}
	}
	var bodyResolved *string = requestBody
	var headersResolved any = requestHeaders
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Coinbase) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil // fallback to default error handler
	}
	var feedback string = this.Id + " " + body
	//
	//    {"error": "invalid_request", "error_description": "The request is missing a required parameter, includes an unsupported parameter value, or is otherwise malformed."}
	//
	// or
	//
	//    {
	//      "errors": [
	//        {
	//          "id": "not_found",
	//          "message": "Not found"
	//        }
	//      ]
	//    }
	// or
	// {
	//     "success": false,
	//     "error_response": {
	//       "error": "UNKNOWN_FAILURE_REASON",
	//       "message": "",
	//       "error_details": "",
	//       "preview_failure_reason": "PREVIEW_STOP_PRICE_ABOVE_LAST_TRADE_PRICE"
	//     },
	//     "order_configuration": {
	//       "stop_limit_stop_limit_gtc": {
	//         "base_size": "0.0001",
	//         "limit_price": "2000",
	//         "stop_price": "2005",
	//         "stop_direction": "STOP_DIRECTION_STOP_DOWN",
	//         "reduce_only": false
	//       }
	//     }
	// }
	//
	var errorCode *string = this.SafeString(response, "error")
	if errorCode != nil {
		var errorMessage *string = this.SafeString2(response, "error_description", "error")
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorMessage, feedback)
		panic(ExchangeError(feedback))
	}
	var errorResponse map[string]any = SafeMapTyped(response, "error_response")
	if errorResponse != nil {
		var errorMessageInner *string = this.SafeString2(errorResponse, "preview_failure_reason", "preview_failure_reason")
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorMessageInner, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorMessageInner, feedback)
		panic(ExchangeError(feedback))
	}
	var errors []any = SafeListTypedDefault(response, "errors", []any{})
	if errors != nil {
		var numErrors int = len(errors)
		if numErrors > 0 {
			errorCode = this.SafeString(errors[0], "id")
			var errorMessage *string = this.SafeString(errors[0], "message")
			if errorCode != nil {
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorCode, feedback)
				this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorMessage, feedback)
				panic(ExchangeError(feedback))
			}
		}
	}
	var advancedTrade *bool = this.SafeBool(this.Options, "advanced")
	if !(InOp(response, "data")) && (advancedTrade == nil || *advancedTrade != true) {
		panic(ExchangeError(this.Id + " failed due to a malformed response " + this.Json(response)))
	}
	return nil
}

/**
 * @method
 * @name coinbase#fetchDepositAddresses
 * @description fetch deposit addresses for multiple currencies (when available)
 * @see https://docs.cdp.coinbase.com/coinbase-app/transfer-apis/onchain-addresses
 * @param {string[]} [codes] list of unified currency codes, default is undefined (all currencies)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.accountId] account ID to fetch deposit addresses for
 * @returns {object} a dictionary of [address structures]{@link https://docs.ccxt.com/?id=address-structure} indexed by currency code
 */
func (this *Coinbase) FetchDepositAddressesAsync(optionalArgs ...any) <-chan AsyncResult[[]DepositAddress] {
	ch := make(chan AsyncResult[[]DepositAddress], 1)
	go this.fetchDepositAddressesBody(ch, optionalArgs...)
	return ch
}
func (this *Coinbase) fetchDepositAddressesBody(ch chan AsyncResult[[]DepositAddress], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var codes []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = codes
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var request map[string]any = this.PrepareAccountRequest(nil, params)

	r1 := <-this.V2PrivateGetAccountsAccountIdAddresses(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- AsyncResult[[]DepositAddress]{Value: DepositAddressesFromList(this.ParseDepositAddresses(data, codes, false, map[string]any{}))}
	return nil
}

func NewCoinbase(userConfig map[string]any) *Coinbase {
	p := newCoinbase()
	p.Init(userConfig)
	return p
}

func (this *Coinbase) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

